from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_group = max(groups)
        INF = len(elements) + 1

        best_index = {}
        for i, value in enumerate(elements):
            if value <= max_group and value not in best_index:
                best_index[value] = i

        assigned = [INF] * (max_group + 1)

        for value, idx in best_index.items():
            for multiple in range(value, max_group + 1, value):
                if idx < assigned[multiple]:
                    assigned[multiple] = idx

        return [assigned[group] if assigned[group] != INF else -1 for group in groups]
